const newFiles = {"src/features/market/UniqueArt.tsx":"import { useId, type ReactNode } from 'react'\n\nexport interface Backdrop { center: string; edge: string; pattern: string }\n\n// Фоны и узоры. Ключи совпадают с unique_traits в базе.\nexport const BACKDROPS: Record<string, Backdrop> = {\n  ash: { center: '#8d8d84', edge: '#6b6b63', pattern: '#4f4f48' },\n  moss: { center: '#80a566', edge: '#4d6d3c', pattern: '#35502a' },\n  sand: { center: '#ecd49f', edge: '#c39b5c', pattern: '#f8ead0' },\n  ocean: { center: '#58bbd9', edge: '#1f6e98', pattern: '#a6e6f7' },\n  rose: { center: '#f2a8bd', edge: '#c9587f', pattern: '#fbd7e2' },\n  plum: { center: '#a671d4', edge: '#5a2f8b', pattern: '#d7b4f2' },\n  sunset: { center: '#ffa46f', edge: '#d4557b', pattern: '#ffd8b0' },\n  midnight: { center: '#30357a', edge: '#12153a', pattern: '#4c52a8' },\n}\n\nexport const SYMBOLS: Record<string, string> = {\n  star: 'M12 2l2.9 6.6 7.1.6-5.4 4.7 1.7 7-6.3-3.8-6.3 3.8 1.7-7L2 9.2l7.1-.6z',\n  moon: 'M20 14.5A8.5 8.5 0 0 1 9.5 4a8.5 8.5 0 1 0 10.5 10.5z',\n  heart: 'M12 21s-8-5.2-8-11a4.5 4.5 0 0 1 8-2.8A4.5 4.5 0 0 1 20 10c0 5.8-8 11-8 11z',\n  diamond: 'M12 2 21 12 12 22 3 12z',\n  leaf: 'M12 22C6 18 4 12 5 4c7 0 12 4 12 11 0 3-2 5-5 7z',\n  bolt: 'M13 2 4 14h6l-1 8 9-12h-6z',\n  sun: 'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10zM11 1h2v3h-2zM11 20h2v3h-2zM1 11h3v2H1zM20 11h3v2h-3zM4.2 5.6l1.4-1.4 2.1 2.1-1.4 1.4zM16.3 17.7l1.4-1.4 2.1 2.1-1.4 1.4zM4.2 18.4l2.1-2.1 1.4 1.4-2.1 2.1zM16.3 6.3l2.1-2.1 1.4 1.4-2.1 2.1z',\n}\n\nconst TICKS = Array.from({ length: 12 }, (_, i) => {\n  const a = (i * Math.PI) / 6\n  const long = i % 3 === 0\n  const r1 = long ? 31 : 34\n  return { x1: 100 + r1 * Math.sin(a), y1: 100 - r1 * Math.cos(a), x2: 100 + 38 * Math.sin(a), y2: 100 - 38 * Math.cos(a), long }\n})\n\nfunction Straps({ fill, stroke }: { fill: string; stroke: string }) {\n  return (\n    <>\n      <rect x=\"80\" y=\"10\" width=\"40\" height=\"58\" rx=\"9\" fill={fill} stroke={stroke} strokeWidth=\"3\" />\n      <rect x=\"80\" y=\"132\" width=\"40\" height=\"58\" rx=\"9\" fill={fill} stroke={stroke} strokeWidth=\"3\" />\n    </>\n  )\n}\n\nfunction Model({ k, uid }: { k: string; uid: string }): ReactNode {\n  if (k === 'pixel') {\n    return (\n      <g>\n        <Straps fill=\"#40586a\" stroke=\"#22343f\" />\n        <rect x=\"153\" y=\"93\" width=\"9\" height=\"14\" rx=\"3\" fill=\"#6e645e\" />\n        <circle cx=\"100\" cy=\"100\" r=\"55\" fill=\"#908580\" stroke=\"#4b423d\" strokeWidth=\"4\" />\n        <circle cx=\"100\" cy=\"100\" r=\"45\" fill=\"#6f6560\" />\n        <circle cx=\"100\" cy=\"100\" r=\"39\" fill=\"#0f7a37\" stroke=\"#86efa8\" strokeWidth=\"2\" />\n        <text x=\"100\" y=\"108\" textAnchor=\"middle\" fontFamily=\"ui-monospace, Menlo, Consolas, monospace\" fontWeight=\"700\" fontSize=\"23\"\n          fill=\"#92ffb3\" style={{ filter: 'drop-shadow(0 0 3px #4dff8a)' }}>12:50</text>\n      </g>\n    )\n  }\n  if (k === 'classic') {\n    return (\n      <g>\n        <Straps fill=\"#6a4330\" stroke=\"#3a2418\" />\n        <rect x=\"153\" y=\"93\" width=\"9\" height=\"14\" rx=\"3\" fill=\"#c9c9d0\" />\n        <circle cx=\"100\" cy=\"100\" r=\"55\" fill=\"#d9d9df\" stroke=\"#8d8d98\" strokeWidth=\"4\" />\n        <circle cx=\"100\" cy=\"100\" r=\"43\" fill=\"#fbfbfd\" stroke=\"#b9b9c4\" strokeWidth=\"2\" />\n        {TICKS.map((t, i) => <line key={i} x1={t.x1} y1={t.y1} x2={t.x2} y2={t.y2} stroke=\"#2a2a33\" strokeWidth={t.long ? 3 : 1.5} strokeLinecap=\"round\" />)}\n        <line x1=\"100\" y1=\"100\" x2=\"82\" y2=\"87\" stroke=\"#1d1d25\" strokeWidth=\"4\" strokeLinecap=\"round\" />\n        <line x1=\"100\" y1=\"100\" x2=\"128\" y2=\"84\" stroke=\"#1d1d25\" strokeWidth=\"2.6\" strokeLinecap=\"round\" />\n        <circle cx=\"100\" cy=\"100\" r=\"3.5\" fill=\"#d23b4a\" />\n      </g>\n    )\n  }\n  if (k === 'neon') {\n    return (\n      <g>\n        <Straps fill=\"#1c1c33\" stroke=\"#ff4fd8\" />\n        <rect x=\"153\" y=\"93\" width=\"9\" height=\"14\" rx=\"3\" fill=\"#35e0ff\" />\n        <circle cx=\"100\" cy=\"100\" r=\"55\" fill=\"#26263f\" stroke=\"#35e0ff\" strokeWidth=\"4\" style={{ filter: 'drop-shadow(0 0 4px #35e0ff)' }} />\n        <circle cx=\"100\" cy=\"100\" r=\"42\" fill=\"#090914\" />\n        <text x=\"100\" y=\"108\" textAnchor=\"middle\" fontFamily=\"ui-monospace, Menlo, Consolas, monospace\" fontWeight=\"700\" fontSize=\"24\"\n          fill=\"#ff6fe0\" style={{ filter: 'drop-shadow(0 0 4px #ff4fd8)' }}>21:07</text>\n      </g>\n    )\n  }\n  if (k === 'gold') {\n    return (\n      <g>\n        <defs>\n          <linearGradient id={`gold${uid}`} x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n            <stop offset=\"0\" stopColor=\"#fbe58a\" /><stop offset=\".55\" stopColor=\"#d9a62c\" /><stop offset=\"1\" stopColor=\"#a8761a\" />\n          </linearGradient>\n        </defs>\n        <Straps fill=\"#2b2b2f\" stroke=\"#111114\" />\n        <rect x=\"153\" y=\"93\" width=\"9\" height=\"14\" rx=\"3\" fill={`url(#gold${uid})`} />\n        <circle cx=\"100\" cy=\"100\" r=\"55\" fill={`url(#gold${uid})`} stroke=\"#8a5f12\" strokeWidth=\"4\" />\n        <circle cx=\"100\" cy=\"100\" r=\"43\" fill=\"#1b1b1f\" stroke=\"#f3cf68\" strokeWidth=\"2\" />\n        {TICKS.map((t, i) => <line key={i} x1={t.x1} y1={t.y1} x2={t.x2} y2={t.y2} stroke=\"#f3cf68\" strokeWidth={t.long ? 3 : 1.5} strokeLinecap=\"round\" />)}\n        <line x1=\"100\" y1=\"100\" x2=\"82\" y2=\"87\" stroke=\"#f3cf68\" strokeWidth=\"4\" strokeLinecap=\"round\" />\n        <line x1=\"100\" y1=\"100\" x2=\"128\" y2=\"84\" stroke=\"#f3cf68\" strokeWidth=\"2.6\" strokeLinecap=\"round\" />\n        <circle cx=\"100\" cy=\"100\" r=\"3.5\" fill=\"#fbe58a\" />\n      </g>\n    )\n  }\n  return (\n    <g>\n      <circle cx=\"100\" cy=\"100\" r=\"50\" fill=\"#555\" />\n      <text x=\"100\" y=\"112\" textAnchor=\"middle\" fontSize=\"38\" fill=\"#fff\">?</text>\n    </g>\n  )\n}\n\nconst CSS = '.ua-float{animation:ua-float 4.5s ease-in-out infinite}@keyframes ua-float{0%,100%{transform:translateY(2px)}50%{transform:translateY(-3px)}}@media (prefers-reduced-motion:reduce){.ua-float{animation:none}}'\n\ninterface Props { model: string; backdrop: string; symbol: string; className?: string; label?: string }\n\n// Картинка уникального подарка: фон с узором и модель по центру.\nexport default function UniqueArt({ model, backdrop, symbol, className = 'rounded-xl', label = 'Уникальный подарок' }: Props) {\n  const uid = useId().replace(/[^a-zA-Z0-9]/g, '')\n  const b = BACKDROPS[backdrop] ?? BACKDROPS.ash\n  const sym = SYMBOLS[symbol] ?? SYMBOLS.star\n  return (\n    <svg viewBox=\"0 0 200 200\" role=\"img\" aria-label={label} className={`block aspect-square w-full ${className}`}>\n      <style>{CSS}</style>\n      <defs>\n        <radialGradient id={`bg${uid}`} cx=\"50%\" cy=\"45%\" r=\"75%\">\n          <stop offset=\"0\" stopColor={b.center} /><stop offset=\"1\" stopColor={b.edge} />\n        </radialGradient>\n        <pattern id={`pt${uid}`} width=\"56\" height=\"56\" patternUnits=\"userSpaceOnUse\">\n          <g fill={b.pattern} opacity=\".42\">\n            <path transform=\"translate(2 2) scale(1.05)\" d={sym} />\n            <path transform=\"translate(30 30) scale(1.05)\" d={sym} />\n          </g>\n        </pattern>\n      </defs>\n      <rect width=\"200\" height=\"200\" fill={`url(#bg${uid})`} />\n      <rect width=\"200\" height=\"200\" fill={`url(#pt${uid})`} />\n      <ellipse cx=\"100\" cy=\"176\" rx=\"46\" ry=\"6\" fill=\"#000\" opacity=\".18\" />\n      <g className=\"ua-float\"><Model k={model} uid={uid} /></g>\n    </svg>\n  )\n}\n","src/features/market/unique.ts":"import { useEffect, useState } from 'react'\nimport { supabase } from '../../lib/supabase'\n\nexport type TraitKind = 'model' | 'backdrop' | 'symbol'\nexport interface UniqueGift {\n  id: string; collection_id: string; number: number; model: string; backdrop: string; symbol: string\n  owner_id: string; price: number | null; shown: boolean; created_at: string\n}\nexport interface Trait { collection_id: string; kind: TraitKind; key: string; title: string; weight: number }\nexport interface Collection { id: string; title: string; description: string; supply: number; minted: number }\nexport interface HistoryRow { id: string; kind: 'mint' | 'send' | 'sale'; from_id: string | null; to_id: string | null; price: number | null; at: string }\n\nconst COLS = 'id, collection_id, number, model, backdrop, symbol, owner_id, price, shown, created_at'\n\nexport const KIND_TITLE: Record<TraitKind, string> = { model: 'Модель', backdrop: 'Фон', symbol: 'Узор' }\n\nexport async function myUnique(userId: string): Promise<UniqueGift[]> {\n  const { data, error } = await supabase.from('unique_gifts').select(COLS).eq('owner_id', userId).order('created_at', { ascending: false })\n  if (error) throw error\n  return data as UniqueGift[]\n}\n\nexport async function profileUnique(userId: string): Promise<UniqueGift[]> {\n  const { data, error } = await supabase.from('unique_gifts').select(COLS).eq('owner_id', userId).eq('shown', true).order('created_at', { ascending: false })\n  if (error) throw error\n  return data as UniqueGift[]\n}\n\nexport async function uniqueForSale(): Promise<UniqueGift[]> {\n  const { data, error } = await supabase.from('unique_gifts').select(COLS).not('price', 'is', null).order('price', { ascending: true }).limit(60)\n  if (error) throw error\n  return data as UniqueGift[]\n}\n\nexport async function getUnique(id: string): Promise<UniqueGift | null> {\n  const { data, error } = await supabase.from('unique_gifts').select(COLS).eq('id', id).maybeSingle()\n  if (error) throw error\n  return (data as UniqueGift | null) ?? null\n}\n\nexport async function uniqueHistory(id: string): Promise<HistoryRow[]> {\n  const { data, error } = await supabase.from('unique_history').select('id, kind, from_id, to_id, price, at').eq('unique_id', id).order('at', { ascending: false })\n  if (error) throw error\n  return data as HistoryRow[]\n}\n\nexport async function upgradeGift(ownedId: string): Promise<string> {\n  const { data, error } = await supabase.rpc('upgrade_gift', { p_ug: ownedId })\n  if (error) throw error\n  const id = String(data)\n  window.dispatchEvent(new CustomEvent('sunset:unique-open', { detail: id }))\n  return id\n}\n\nexport async function sendUnique(id: string, toId: string): Promise<void> {\n  const { error } = await supabase.rpc('send_unique', { p_id: id, p_to: toId })\n  if (error) throw error\n}\nexport async function setUniqueShown(id: string, shown: boolean): Promise<void> {\n  const { error } = await supabase.rpc('set_unique_shown', { p_id: id, p_shown: shown })\n  if (error) throw error\n}\nexport async function listUnique(id: string, price: number | null): Promise<void> {\n  const { error } = await supabase.rpc('list_unique', { p_id: id, p_price: price })\n  if (error) throw error\n}\nexport async function buyUnique(id: string): Promise<void> {\n  const { error } = await supabase.rpc('buy_unique', { p_id: id })\n  if (error) throw error\n}\n\nexport function friendlyUnique(msg: string): string {\n  if (msg.includes('not enough stars')) return 'Недостаточно Звёзд.'\n  if (msg.includes('sold out')) return 'Тираж этой коллекции закончился.'\n  if (msg.includes('not your gift')) return 'Этого подарка у вас уже нет.'\n  if (msg.includes('not upgradable')) return 'Этот подарок нельзя улучшить.'\n  if (msg.includes('item not for sale')) return 'Подарок уже не продаётся.'\n  if (msg.includes('already yours')) return 'Это ваш подарок.'\n  if (msg.includes('bad price')) return 'Некорректная цена.'\n  if (msg.includes('bad recipient')) return 'Нельзя подарить этому пользователю.'\n  if (msg.includes('unique_') || msg.includes('schema cache')) return 'Уникальные подарки не настроены: выполните SQL 0018.'\n  return msg\n}\n\nexport interface Meta { collections: Map<string, Collection>; traits: Map<string, Trait>; totals: Map<string, number> }\nlet metaPromise: Promise<Meta> | null = null\n\nexport function loadMeta(): Promise<Meta> {\n  if (!metaPromise) {\n    metaPromise = (async () => {\n      const [c, t] = await Promise.all([\n        supabase.from('unique_collections').select('id, title, description, supply, minted'),\n        supabase.from('unique_traits').select('collection_id, kind, key, title, weight'),\n      ])\n      if (c.error) throw c.error\n      if (t.error) throw t.error\n      const collections = new Map((c.data as Collection[]).map((x) => [x.id, x]))\n      const traits = new Map<string, Trait>()\n      const totals = new Map<string, number>()\n      for (const tr of t.data as Trait[]) {\n        traits.set(`${tr.collection_id}:${tr.kind}:${tr.key}`, tr)\n        const tk = `${tr.collection_id}:${tr.kind}`\n        totals.set(tk, (totals.get(tk) ?? 0) + tr.weight)\n      }\n      return { collections, traits, totals }\n    })().catch((e: unknown) => { metaPromise = null; throw e })\n  }\n  return metaPromise\n}\n\nexport function useMeta(): Meta | null {\n  const [m, setM] = useState<Meta | null>(null)\n  useEffect(() => {\n    let alive = true\n    void loadMeta().then((x) => { if (alive) setM(x) }).catch(() => undefined)\n    return () => { alive = false }\n  }, [])\n  return m\n}\n\nexport function traitOf(meta: Meta | null, g: UniqueGift, kind: TraitKind): { title: string; percent: number | null } {\n  const key = g[kind]\n  const t = meta?.traits.get(`${g.collection_id}:${kind}:${key}`)\n  const total = meta?.totals.get(`${g.collection_id}:${kind}`)\n  return { title: t?.title ?? key, percent: t && total ? Math.round((t.weight / total) * 1000) / 10 : null }\n}\n\nexport function uniqueTitle(meta: Meta | null, g: UniqueGift): string {\n  return `${meta?.collections.get(g.collection_id)?.title ?? 'Подарок'} #${g.number}`\n}\n","src/features/market/UniqueModal.tsx":"import { useCallback, useEffect, useState } from 'react'\nimport { createPortal } from 'react-dom'\nimport { Eye, EyeOff, Loader2, Star, Tag, X } from 'lucide-react'\nimport { supabase } from '../../lib/supabase'\nimport { getStars } from '../chat/api'\nimport UniqueArt from './UniqueArt'\nimport {\n  KIND_TITLE, buyUnique, friendlyUnique, getUnique, listUnique, setUniqueShown, traitOf, uniqueHistory, uniqueTitle, useMeta,\n  type HistoryRow, type TraitKind, type UniqueGift,\n} from './unique'\n\ninterface Props { id: string; initial?: UniqueGift; onClose: () => void; onChanged?: () => void }\n\nconst fmt = (n: number) => n.toLocaleString('ru-RU')\n\n// Карточка уникального подарка: картинка, редкость и атрибуты, цена, история.\nexport default function UniqueModal({ id, initial, onClose, onChanged }: Props) {\n  const meta = useMeta()\n  const [g, setG] = useState<UniqueGift | null>(initial ?? null)\n  const [me, setMe] = useState('')\n  const [stars, setStars] = useState(0)\n  const [names, setNames] = useState<Record<string, string>>({})\n  const [hist, setHist] = useState<HistoryRow[]>([])\n  const [tab, setTab] = useState<'details' | 'history'>('details')\n  const [priceIn, setPriceIn] = useState('')\n  const [selling, setSelling] = useState(false)\n  const [busy, setBusy] = useState(false)\n  const [err, setErr] = useState<string | null>(null)\n  const [missing, setMissing] = useState(false)\n\n  const load = useCallback(async () => {\n    try {\n      const [u, h, s, sess] = await Promise.all([getUnique(id), uniqueHistory(id), getStars().catch(() => 0), supabase.auth.getSession()])\n      setMe(sess.data.session?.user.id ?? '')\n      setStars(s)\n      if (!u) { setMissing(true); return }\n      setG(u); setHist(h)\n      const ids = [...new Set([u.owner_id, ...h.flatMap((r) => [r.from_id, r.to_id]).filter((x): x is string => !!x)])]\n      const { data } = await supabase.from('profiles').select('id, display_name').in('id', ids)\n      const map: Record<string, string> = {}\n      for (const p of (data ?? []) as { id: string; display_name: string }[]) map[p.id] = p.display_name\n      setNames(map)\n    } catch (e) { setErr(friendlyUnique(e instanceof Error ? e.message : String(e))) }\n  }, [id])\n\n  useEffect(() => { void load() }, [load])\n  useEffect(() => {\n    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose() }\n    document.addEventListener('keydown', onKey)\n    return () => document.removeEventListener('keydown', onKey)\n  }, [onClose])\n\n  async function act(fn: () => Promise<void>) {\n    setBusy(true); setErr(null)\n    try { await fn(); await load(); onChanged?.() }\n    catch (e) { setErr(friendlyUnique(e instanceof Error ? e.message : (e as { message?: string }).message ?? String(e))) }\n    finally { setBusy(false) }\n  }\n\n  const mine = !!g && g.owner_id === me\n  const title = g ? uniqueTitle(meta, g) : ''\n  const nm = (uid: string | null) => (uid ? names[uid] ?? '…' : '—')\n\n  const attr = (g2: UniqueGift, kind: TraitKind) => {\n    const t = traitOf(meta, g2, kind)\n    return (\n      <div key={kind} className=\"rounded-2xl border border-line px-4 py-3\">\n        <div className=\"text-xs font-medium text-accent\">{KIND_TITLE[kind]}</div>\n        <div className=\"mt-0.5 flex items-baseline justify-between gap-2\">\n          <span className=\"truncate font-semibold\">{t.title}</span>\n          {t.percent !== null && <span className=\"shrink-0 text-xs text-muted\">{t.percent}%</span>}\n        </div>\n      </div>\n    )\n  }\n\n  return createPortal(\n    <div data-sticker-modal className=\"fixed inset-0 z-[60] flex items-center justify-center bg-black/75 p-0 md:p-6\" onClick={onClose}>\n      <div className=\"relative max-h-full w-full max-w-4xl overflow-y-auto bg-bg2 md:rounded-3xl md:border md:border-line\" onClick={(e) => e.stopPropagation()}>\n        <button type=\"button\" onClick={onClose} className=\"absolute right-3 top-3 z-10 rounded-full bg-bg2/80 p-1.5 text-muted transition hover:text-text\"><X size={18} /></button>\n        {missing && <p className=\"p-10 text-center text-sm text-muted\">Подарок не найден или скрыт владельцем.</p>}\n        {!missing && !g && <div className=\"p-10 text-center text-sm text-muted\">{err ?? 'Загрузка…'}</div>}\n        {g && (\n          <div className=\"grid gap-6 p-5 md:grid-cols-2 md:p-6\">\n            <div className=\"md:sticky md:top-0 md:self-start\">\n              <UniqueArt model={g.model} backdrop={g.backdrop} symbol={g.symbol} className=\"rounded-3xl\" label={title} />\n            </div>\n            <div className=\"min-w-0 space-y-4\">\n              <div>\n                <div className=\"flex flex-wrap items-center gap-2 pr-8\">\n                  <h2 className=\"text-2xl font-bold\">{title}</h2>\n                  {g.price !== null && <span className=\"rounded-full bg-accent/15 px-2.5 py-0.5 text-xs font-medium text-accent\">На продаже</span>}\n                </div>\n                <p className=\"mt-1 text-sm text-muted\">\n                  {meta?.collections.get(g.collection_id)?.title ?? 'Коллекция'} · владелец {nm(g.owner_id)}\n                </p>\n              </div>\n\n              {g.price !== null && (\n                <div>\n                  <div className=\"text-xs text-muted\">Цена</div>\n                  <div className=\"flex items-center gap-1.5 text-2xl font-bold\"><Star size={20} className=\"text-accent\" fill=\"currentColor\" />{fmt(g.price)}</div>\n                </div>\n              )}\n\n              {!mine && g.price !== null && (\n                stars < g.price\n                  ? <button type=\"button\" disabled className=\"w-full rounded-2xl bg-surface py-3 text-sm font-semibold text-muted\">Не хватает Звёзд</button>\n                  : <button type=\"button\" disabled={busy} onClick={() => void act(() => buyUnique(g.id))}\n                      className=\"flex w-full items-center justify-center gap-2 rounded-2xl bg-accent py-3 text-sm font-semibold text-on-accent transition hover:brightness-110 disabled:opacity-60\">\n                      {busy && <Loader2 size={14} className=\"animate-spin\" />}Купить за {fmt(g.price)}\n                    </button>\n              )}\n\n              {mine && (\n                <div className=\"space-y-2\">\n                  <div className=\"flex flex-wrap gap-2\">\n                    <button type=\"button\" disabled={busy} onClick={() => void act(() => setUniqueShown(g.id, !g.shown))}\n                      className=\"flex items-center gap-1.5 rounded-xl bg-surface px-3 py-2 text-sm transition hover:text-accent disabled:opacity-60\">\n                      {g.shown ? <><EyeOff size={15} />Скрыть из профиля</> : <><Eye size={15} />Показать в профиле</>}\n                    </button>\n                    {g.price !== null ? (\n                      <button type=\"button\" disabled={busy} onClick={() => void act(() => listUnique(g.id, null))}\n                        className=\"flex items-center gap-1.5 rounded-xl bg-surface px-3 py-2 text-sm transition hover:text-accent disabled:opacity-60\"><Tag size={15} />Снять с продажи</button>\n                    ) : (\n                      <button type=\"button\" onClick={() => setSelling((v) => !v)}\n                        className=\"flex items-center gap-1.5 rounded-xl bg-surface px-3 py-2 text-sm transition hover:text-accent\"><Tag size={15} />Продать</button>\n                    )}\n                  </div>\n                  {selling && g.price === null && (\n                    <div className=\"flex gap-2\">\n                      <input value={priceIn} inputMode=\"numeric\" placeholder=\"Цена в Звёздах\"\n                        onChange={(e) => setPriceIn(e.target.value.replace(/\\D/g, '').slice(0, 10))}\n                        className=\"min-w-0 flex-1 rounded-xl bg-surface px-3 py-2 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-accent\" />\n                      <button type=\"button\" disabled={busy || !priceIn || Number(priceIn) < 1}\n                        onClick={() => void act(async () => { await listUnique(g.id, Number(priceIn)); setSelling(false); setPriceIn('') })}\n                        className=\"rounded-xl bg-accent px-4 py-2 text-sm font-semibold text-on-accent disabled:opacity-50\">Выставить</button>\n                    </div>\n                  )}\n                  <p className=\"text-xs text-muted\">Подарить другу можно из окна информации о чате, кнопка «Подарок».</p>\n                </div>\n              )}\n              {err && <p className=\"text-sm text-pink\">{err}</p>}\n\n              <div className=\"flex gap-1 border-b border-line\">\n                {(['details', 'history'] as const).map((t) => (\n                  <button key={t} type=\"button\" onClick={() => setTab(t)}\n                    className={`-mb-px border-b-2 px-4 py-2 text-sm font-medium transition ${tab === t ? 'border-accent text-text' : 'border-transparent text-muted hover:text-text'}`}>\n                    {t === 'details' ? 'Детали' : 'История'}\n                  </button>\n                ))}\n              </div>\n\n              {tab === 'details' ? (\n                <div className=\"space-y-4\">\n                  <div>\n                    <h3 className=\"mb-2 font-semibold\">Редкость и атрибуты</h3>\n                    <div className=\"grid grid-cols-2 gap-2\">{(['model', 'backdrop', 'symbol'] as TraitKind[]).map((k) => attr(g, k))}</div>\n                    <p className=\"mt-2 text-xs text-muted\">Процент показывает, как часто такой признак выпадает: чем меньше, тем реже.</p>\n                  </div>\n                  <div>\n                    <h3 className=\"mb-1 font-semibold\">Описание</h3>\n                    <p className=\"text-sm text-muted\">\n                      Уникальные {meta?.collections.get(g.collection_id)?.title.toLowerCase() ?? 'предметы'}: модель «{traitOf(meta, g, 'model').title}»,\n                      фон «{traitOf(meta, g, 'backdrop').title}», узор «{traitOf(meta, g, 'symbol').title}».\n                      Номер {g.number} из {fmt(meta?.collections.get(g.collection_id)?.supply ?? 0)}.\n                    </p>\n                  </div>\n                </div>\n              ) : (\n                <ul className=\"space-y-2 text-sm\">\n                  {hist.length === 0 && <li className=\"text-muted\">Событий пока нет.</li>}\n                  {hist.map((h) => (\n                    <li key={h.id} className=\"flex items-start justify-between gap-3 rounded-2xl bg-surface px-3 py-2\">\n                      <span className=\"min-w-0\">\n                        {h.kind === 'mint' && <>Улучшен до уникального · {nm(h.to_id)}</>}\n                        {h.kind === 'send' && <>Подарок: {nm(h.from_id)} → {nm(h.to_id)}</>}\n                        {h.kind === 'sale' && <>Продажа: {nm(h.from_id)} → {nm(h.to_id)}{h.price ? ` · ${fmt(h.price)} ★` : ''}</>}\n                      </span>\n                      <span className=\"shrink-0 text-xs text-muted\">{new Date(h.at).toLocaleDateString('ru-RU')}</span>\n                    </li>\n                  ))}\n                </ul>\n              )}\n            </div>\n          </div>\n        )}\n      </div>\n    </div>,\n    document.body,\n  )\n}\n","src/features/market/UniqueLists.tsx":"import { useCallback, useEffect, useState } from 'react'\nimport { Star } from 'lucide-react'\nimport UniqueArt from './UniqueArt'\nimport UniqueModal from './UniqueModal'\nimport { myUnique, uniqueForSale, uniqueTitle, useMeta, type UniqueGift } from './unique'\n\nexport function UniqueCard({ g, onOpen }: { g: UniqueGift; onOpen: (id: string) => void }) {\n  const meta = useMeta()\n  return (\n    <button type=\"button\" onClick={() => onOpen(g.id)} className=\"flex flex-col gap-2 rounded-2xl bg-surface p-2 text-left transition hover:brightness-110\">\n      <UniqueArt model={g.model} backdrop={g.backdrop} symbol={g.symbol} className=\"rounded-xl\" label={uniqueTitle(meta, g)} />\n      <div className=\"px-1 pb-1\">\n        <div className=\"truncate text-sm font-medium\">{uniqueTitle(meta, g)}</div>\n        <div className=\"flex items-center gap-2 text-xs text-muted\">\n          {g.price !== null && <span className=\"flex items-center gap-0.5 text-accent\"><Star size={11} fill=\"currentColor\" />{g.price.toLocaleString('ru-RU')}</span>}\n          {g.shown && g.price === null && <span>в профиле</span>}\n        </div>\n      </div>\n    </button>\n  )\n}\n\n// Мои уникальные подарки (Маркет → Мои → Подарки).\nexport function UniqueMine({ meId, reloadKey, onChanged }: { meId: string; reloadKey: string; onChanged: () => void }) {\n  const [list, setList] = useState<UniqueGift[]>([])\n  const [open, setOpen] = useState<string | null>(null)\n\n  const load = useCallback(() => { void myUnique(meId).then(setList).catch(() => undefined) }, [meId])\n  useEffect(() => { load() }, [load, reloadKey])\n  useEffect(() => {\n    const on = (e: Event) => { load(); setOpen(String((e as CustomEvent).detail)) }\n    window.addEventListener('sunset:unique-open', on)\n    return () => window.removeEventListener('sunset:unique-open', on)\n  }, [load])\n\n  return (\n    <>\n      {list.length > 0 && (\n        <div className=\"space-y-2\">\n          <h3 className=\"text-sm font-semibold text-muted\">Уникальные подарки · {list.length}</h3>\n          <div className=\"grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4\">{list.map((g) => <UniqueCard key={g.id} g={g} onOpen={setOpen} />)}</div>\n        </div>\n      )}\n      {open && <UniqueModal id={open} onClose={() => setOpen(null)} onChanged={() => { load(); onChanged() }} />}\n    </>\n  )\n}\n\n// Уникальные подарки на продаже (Маркет → Подарки).\nexport function UniqueShop({ reloadKey, onChanged }: { reloadKey: string; onChanged: () => void }) {\n  const [list, setList] = useState<UniqueGift[]>([])\n  const [open, setOpen] = useState<string | null>(null)\n  const load = useCallback(() => { void uniqueForSale().then(setList).catch(() => undefined) }, [])\n  useEffect(() => { load() }, [load, reloadKey])\n  if (list.length === 0 && !open) return null\n  return (\n    <>\n      <div className=\"space-y-2\">\n        <h3 className=\"text-sm font-semibold text-muted\">Уникальные подарки на продаже · {list.length}</h3>\n        <div className=\"grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4\">{list.map((g) => <UniqueCard key={g.id} g={g} onOpen={setOpen} />)}</div>\n      </div>\n      {open && <UniqueModal id={open} onClose={() => setOpen(null)} onChanged={() => { load(); onChanged() }} />}\n    </>\n  )\n}\n","src/features/market/ProfileGifts.tsx":"import { useEffect, useState } from 'react'\nimport GiftArt from './GiftArt'\nimport UniqueArt from './UniqueArt'\nimport UniqueModal from './UniqueModal'\nimport { listGifts, profileGifts, type Gift, type OwnedGift } from './gifts'\nimport { profileUnique, uniqueTitle, useMeta, type UniqueGift } from './unique'\n\ninterface Props { userId: string; title?: string; reloadKey?: number }\n\nexport default function ProfileGifts({ userId, title = 'Подарки', reloadKey = 0 }: Props) {\n  const meta = useMeta()\n  const [items, setItems] = useState<OwnedGift[]>([])\n  const [uniq, setUniq] = useState<UniqueGift[]>([])\n  const [catalog, setCatalog] = useState<Map<string, Gift>>(new Map())\n  const [open, setOpen] = useState<string | null>(null)\n\n  useEffect(() => {\n    let active = true\n    Promise.all([profileGifts(userId), listGifts()])\n      .then(([own, gifts]) => { if (active) { setItems(own); setCatalog(new Map(gifts.map((g) => [g.id, g]))) } })\n      .catch(() => undefined)\n    profileUnique(userId).then((u) => { if (active) setUniq(u) }).catch(() => undefined)\n    return () => { active = false }\n  }, [userId, reloadKey])\n\n  const total = items.length + uniq.length\n  if (total === 0) return null\n  const shownUniq = uniq.slice(0, 6)\n  const shownRegular = items.slice(0, Math.max(0, 6 - shownUniq.length))\n\n  return (\n    <div>\n      <div className=\"mb-1 px-1 text-xs text-muted\">{title} ({total})</div>\n      <div className=\"grid grid-cols-3 gap-2\">\n        {shownUniq.map((u) => (\n          <button key={u.id} type=\"button\" title={uniqueTitle(meta, u)} onClick={() => setOpen(u.id)} className=\"block text-left transition hover:brightness-110\">\n            <UniqueArt model={u.model} backdrop={u.backdrop} symbol={u.symbol} className=\"rounded-xl\" label={uniqueTitle(meta, u)} />\n          </button>\n        ))}\n        {shownRegular.map((it) => {\n          const g = catalog.get(it.gift_id)\n          const hint = [g?.title, it.sender ? `от ${it.sender.display_name}` : null, it.note].filter(Boolean).join(' · ')\n          return g ? <div key={it.id} title={hint}><GiftArt gift={g} /></div> : null\n        })}\n      </div>\n      {total > shownUniq.length + shownRegular.length && <div className=\"mt-1 px-1 text-xs text-muted\">и ещё {total - shownUniq.length - shownRegular.length}</div>}\n      {open && <UniqueModal id={open} onClose={() => setOpen(null)} />}\n    </div>\n  )\n}\n","src/features/market/GiftSendModal.tsx":"import { useEffect, useState } from 'react'\nimport { Loader2 } from 'lucide-react'\nimport { sendMessage } from '../chat/api'\nimport GiftArt from './GiftArt'\nimport UniqueArt from './UniqueArt'\nimport { listGifts, myGifts, sendGift, type Gift, type OwnedGift } from './gifts'\nimport { friendlyUnique, myUnique, sendUnique, uniqueTitle, useMeta, type UniqueGift } from './unique'\n\ninterface Props {\n  myId: string\n  toId: string\n  toName: string\n  chatId: string\n  onClose: () => void\n  onSent: () => void\n}\n\nfunction friendly(msg: string): string {\n  if (msg.includes('not your gift')) return 'Этого подарка у вас уже нет.'\n  if (msg.includes('bad recipient')) return 'Нельзя подарить этому пользователю.'\n  return friendlyUnique(msg)\n}\n\nexport default function GiftSendModal({ myId, toId, toName, chatId, onClose, onSent }: Props) {\n  const meta = useMeta()\n  const [owned, setOwned] = useState<OwnedGift[] | null>(null)\n  const [uniq, setUniq] = useState<UniqueGift[]>([])\n  const [catalog, setCatalog] = useState<Map<string, Gift>>(new Map())\n  const [selected, setSelected] = useState<string | null>(null)\n  const [note, setNote] = useState('')\n  const [busy, setBusy] = useState(false)\n  const [error, setError] = useState<string | null>(null)\n\n  useEffect(() => {\n    Promise.all([myGifts(myId), listGifts()])\n      .then(([own, gifts]) => { setOwned(own); setCatalog(new Map(gifts.map((g) => [g.id, g]))) })\n      .catch((e: Error) => { setOwned([]); setError(friendly(e.message)) })\n    myUnique(myId).then(setUniq).catch(() => undefined)\n  }, [myId])\n\n  async function send() {\n    const item = owned?.find((o) => o.id === selected)\n    const un = uniq.find((u) => u.id === selected)\n    if (!item && !un) return\n    setBusy(true); setError(null)\n    try {\n      let label: string\n      if (un) {\n        await sendUnique(un.id, toId)\n        label = uniqueTitle(meta, un)\n      } else if (item) {\n        await sendGift(item.id, toId, note.trim())\n        label = catalog.get(item.gift_id)?.title ?? 'подарок'\n      } else return\n      const text = `🎁 Подарок «${label}»` + (note.trim() ? `\\n${note.trim()}` : '')\n      await sendMessage(chatId, myId, text, null).catch(() => undefined)\n      onSent()\n      onClose()\n    } catch (e) {\n      setError(friendly((e as Error).message))\n      setBusy(false)\n    }\n  }\n\n  const empty = owned !== null && owned.length === 0 && uniq.length === 0\n\n  return (\n    <div className=\"fixed inset-0 z-40 flex items-center justify-center bg-black/60 p-4\" onClick={onClose}>\n      <div className=\"max-h-[90vh] w-full max-w-md space-y-4 overflow-y-auto rounded-3xl bg-bg2 p-5\" onClick={(e) => e.stopPropagation()}>\n        <h2 className=\"text-lg font-medium\">Подарок для {toName}</h2>\n\n        {owned === null && <p className=\"text-sm text-muted\">Загрузка…</p>}\n        {empty && <p className=\"text-sm text-muted\">У вас пока нет подарков. Купите их в Маркете, вкладка «Магазин».</p>}\n\n        {(uniq.length > 0 || (owned !== null && owned.length > 0)) && (\n          <div className=\"grid grid-cols-2 gap-3\">\n            {uniq.map((u) => (\n              <button key={u.id} onClick={() => setSelected(u.id)}\n                className={`flex flex-col gap-2 rounded-2xl bg-surface p-2 text-left transition ${selected === u.id ? 'ring-2 ring-accent' : 'hover:brightness-110'}`}>\n                <UniqueArt model={u.model} backdrop={u.backdrop} symbol={u.symbol} className=\"rounded-xl\" label={uniqueTitle(meta, u)} />\n                <span className=\"px-1 text-xs\">{uniqueTitle(meta, u)}</span>\n              </button>\n            ))}\n            {(owned ?? []).map((o) => {\n              const g = catalog.get(o.gift_id)\n              return (\n                <button key={o.id} onClick={() => setSelected(o.id)}\n                  className={`flex flex-col gap-2 rounded-2xl bg-surface p-2 text-left transition ${selected === o.id ? 'ring-2 ring-accent' : 'hover:brightness-110'}`}>\n                  {g && <GiftArt gift={g} />}\n                  <span className=\"px-1 text-xs\">{g?.title ?? 'Подарок'}</span>\n                </button>\n              )\n            })}\n          </div>\n        )}\n\n        {selected && (\n          <textarea value={note} maxLength={200} placeholder=\"Подпись (необязательно)\" onChange={(e) => setNote(e.target.value)}\n            className=\"h-20 w-full resize-none rounded-xl bg-surface px-4 py-3 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-accent\" />\n        )}\n        {error && <p className=\"text-sm text-pink\">{error}</p>}\n\n        <div className=\"flex justify-end gap-2\">\n          <button onClick={onClose} className=\"rounded-xl px-4 py-2 text-sm text-muted transition hover:text-text\">Отмена</button>\n          <button onClick={() => void send()} disabled={!selected || busy}\n            className=\"flex items-center gap-2 rounded-xl bg-accent px-4 py-2 text-sm font-semibold text-on-accent transition hover:brightness-110 disabled:opacity-50\">\n            {busy && <Loader2 size={14} className=\"animate-spin\" />} Подарить\n          </button>\n        </div>\n      </div>\n    </div>\n  )\n}\n","supabase/migrations/0018_unique_gifts.sql":"-- Sunset: уникальные подарки (модель + фон + узор, номер в тираже, редкость, перепродажа).\n\nalter table public.gifts add column if not exists collection text;\nalter table public.gifts add column if not exists upgrade_price bigint not null default 0 check (upgrade_price >= 0);\n\ncreate table if not exists public.unique_collections (\n  id text primary key check (id ~ '^[a-z0-9_]{2,40}$'),\n  title text not null,\n  description text not null default '',\n  supply int not null check (supply > 0),\n  minted int not null default 0\n);\n\ncreate table if not exists public.unique_traits (\n  collection_id text not null references public.unique_collections(id) on delete cascade,\n  kind text not null check (kind in ('model', 'backdrop', 'symbol')),\n  key text not null check (key ~ '^[a-z0-9_]{1,30}$'),\n  title text not null,\n  weight int not null check (weight > 0),\n  primary key (collection_id, kind, key)\n);\n\ncreate table if not exists public.unique_gifts (\n  id uuid primary key default gen_random_uuid(),\n  collection_id text not null references public.unique_collections(id),\n  number int not null,\n  model text not null,\n  backdrop text not null,\n  symbol text not null,\n  owner_id uuid not null references public.profiles(id) on delete cascade,\n  price bigint check (price is null or price > 0),\n  shown boolean not null default true,\n  created_at timestamptz not null default now(),\n  unique (collection_id, number)\n);\ncreate index if not exists unique_gifts_owner_idx on public.unique_gifts (owner_id);\ncreate index if not exists unique_gifts_sale_idx on public.unique_gifts (price) where price is not null;\n\ncreate table if not exists public.unique_history (\n  id uuid primary key default gen_random_uuid(),\n  unique_id uuid not null references public.unique_gifts(id) on delete cascade,\n  kind text not null check (kind in ('mint', 'send', 'sale')),\n  from_id uuid references public.profiles(id) on delete set null,\n  to_id uuid references public.profiles(id) on delete set null,\n  price bigint,\n  at timestamptz not null default now()\n);\ncreate index if not exists unique_history_idx on public.unique_history (unique_id, at desc);\n\nalter table public.unique_collections enable row level security;\nalter table public.unique_traits enable row level security;\nalter table public.unique_gifts enable row level security;\nalter table public.unique_history enable row level security;\n\ndrop policy if exists unique_coll_select on public.unique_collections;\ndrop policy if exists unique_traits_select on public.unique_traits;\ndrop policy if exists unique_gifts_select on public.unique_gifts;\ndrop policy if exists unique_history_select on public.unique_history;\ncreate policy unique_coll_select on public.unique_collections for select to authenticated using (true);\ncreate policy unique_traits_select on public.unique_traits for select to authenticated using (true);\ncreate policy unique_gifts_select on public.unique_gifts for select to authenticated\n  using (owner_id = auth.uid() or shown or price is not null);\ncreate policy unique_history_select on public.unique_history for select to authenticated\n  using (exists (select 1 from public.unique_gifts u where u.id = unique_id));\n\nrevoke all on public.unique_collections, public.unique_traits, public.unique_gifts, public.unique_history from anon, authenticated;\ngrant select on public.unique_collections, public.unique_traits, public.unique_gifts, public.unique_history to authenticated;\n\n-- Случайный признак с учётом веса (чем больше вес, тем чаще выпадает).\ncreate or replace function public.pick_trait(p_coll text, p_kind text) returns text\nlanguage sql volatile security definer set search_path = '' as $$\n  select key from public.unique_traits where collection_id = p_coll and kind = p_kind\n  order by -ln(1 - random()) / weight limit 1\n$$;\nrevoke all on function public.pick_trait(text, text) from public, anon, authenticated;\n\n-- Улучшение обычного подарка до уникального.\ncreate or replace function public.upgrade_gift(p_ug uuid) returns uuid\nlanguage plpgsql security definer set search_path = '' as $$\ndeclare v_me uuid := auth.uid(); ug public.user_gifts%rowtype; g public.gifts%rowtype; c public.unique_collections%rowtype;\n        v_id uuid; v_num int;\nbegin\n  if v_me is null then raise exception 'not authenticated'; end if;\n  select * into ug from public.user_gifts where id = p_ug and owner_id = v_me for update;\n  if not found then raise exception 'not your gift'; end if;\n  select * into g from public.gifts where id = ug.gift_id;\n  if g.collection is null then raise exception 'not upgradable'; end if;\n  select * into c from public.unique_collections where id = g.collection for update;\n  if not found or c.minted >= c.supply then raise exception 'sold out'; end if;\n  if g.upgrade_price > 0 then\n    update public.wallets set stars = stars - g.upgrade_price where user_id = v_me and stars >= g.upgrade_price;\n    if not found then raise exception 'not enough stars'; end if;\n  end if;\n  v_num := c.minted + 1;\n  insert into public.unique_gifts (collection_id, number, model, backdrop, symbol, owner_id, shown)\n  values (c.id, v_num, public.pick_trait(c.id, 'model'), public.pick_trait(c.id, 'backdrop'), public.pick_trait(c.id, 'symbol'), v_me, ug.shown)\n  returning id into v_id;\n  update public.unique_collections set minted = v_num where id = c.id;\n  delete from public.user_gifts where id = p_ug;\n  insert into public.unique_history (unique_id, kind, to_id) values (v_id, 'mint', v_me);\n  return v_id;\nend $$;\n\ncreate or replace function public.send_unique(p_id uuid, p_to uuid) returns void\nlanguage plpgsql security definer set search_path = '' as $$\ndeclare v_me uuid := auth.uid();\nbegin\n  if v_me is null then raise exception 'not authenticated'; end if;\n  if p_to is null or p_to = v_me or not exists (select 1 from public.profiles where id = p_to) then raise exception 'bad recipient'; end if;\n  update public.unique_gifts set owner_id = p_to, price = null, shown = true where id = p_id and owner_id = v_me;\n  if not found then raise exception 'not your gift'; end if;\n  insert into public.unique_history (unique_id, kind, from_id, to_id) values (p_id, 'send', v_me, p_to);\nend $$;\n\ncreate or replace function public.set_unique_shown(p_id uuid, p_shown boolean) returns void\nlanguage plpgsql security definer set search_path = '' as $$\nbegin\n  if auth.uid() is null then raise exception 'not authenticated'; end if;\n  update public.unique_gifts set shown = coalesce(p_shown, false) where id = p_id and owner_id = auth.uid();\n  if not found then raise exception 'not your gift'; end if;\nend $$;\n\ncreate or replace function public.list_unique(p_id uuid, p_price bigint) returns void\nlanguage plpgsql security definer set search_path = '' as $$\nbegin\n  if auth.uid() is null then raise exception 'not authenticated'; end if;\n  if p_price is not null and (p_price < 1 or p_price > 1000000000) then raise exception 'bad price'; end if;\n  update public.unique_gifts set price = p_price where id = p_id and owner_id = auth.uid();\n  if not found then raise exception 'not your gift'; end if;\nend $$;\n\ncreate or replace function public.buy_unique(p_id uuid) returns void\nlanguage plpgsql security definer set search_path = '' as $$\ndeclare v_me uuid := auth.uid(); u public.unique_gifts%rowtype;\nbegin\n  if v_me is null then raise exception 'not authenticated'; end if;\n  select * into u from public.unique_gifts where id = p_id for update;\n  if not found or u.price is null then raise exception 'item not for sale'; end if;\n  if u.owner_id = v_me then raise exception 'already yours'; end if;\n  update public.wallets set stars = stars - u.price where user_id = v_me and stars >= u.price;\n  if not found then raise exception 'not enough stars'; end if;\n  insert into public.wallets as w (user_id, stars) values (u.owner_id, u.price)\n    on conflict (user_id) do update set stars = w.stars + excluded.stars;\n  update public.unique_gifts set owner_id = v_me, price = null, shown = true where id = p_id;\n  insert into public.unique_history (unique_id, kind, from_id, to_id, price) values (p_id, 'sale', u.owner_id, v_me, u.price);\nend $$;\n\nrevoke all on function public.upgrade_gift(uuid), public.send_unique(uuid, uuid), public.set_unique_shown(uuid, boolean),\n  public.list_unique(uuid, bigint), public.buy_unique(uuid) from public, anon;\ngrant execute on function public.upgrade_gift(uuid), public.send_unique(uuid, uuid), public.set_unique_shown(uuid, boolean),\n  public.list_unique(uuid, bigint), public.buy_unique(uuid) to authenticated;\n\n-- Первая коллекция: «Закатные часы». Ключи признаков связаны с рисунками в приложении (UniqueArt.tsx).\ninsert into public.unique_collections (id, title, description, supply)\nvalues ('sunset_watch', 'Закатные часы', 'Коллекционные часы Sunset: у каждых своя модель, фон и узор.', 10000)\non conflict (id) do nothing;\n\ninsert into public.unique_traits (collection_id, kind, key, title, weight) values\n  ('sunset_watch', 'model', 'pixel', 'Пиксель', 40),\n  ('sunset_watch', 'model', 'classic', 'Классика', 30),\n  ('sunset_watch', 'model', 'neon', 'Неон', 20),\n  ('sunset_watch', 'model', 'gold', 'Золото', 10),\n  ('sunset_watch', 'backdrop', 'ash', 'Пепельный', 20),\n  ('sunset_watch', 'backdrop', 'moss', 'Мох', 15),\n  ('sunset_watch', 'backdrop', 'sand', 'Песок', 15),\n  ('sunset_watch', 'backdrop', 'ocean', 'Океан', 14),\n  ('sunset_watch', 'backdrop', 'rose', 'Роза', 12),\n  ('sunset_watch', 'backdrop', 'plum', 'Слива', 10),\n  ('sunset_watch', 'backdrop', 'sunset', 'Закатный', 8),\n  ('sunset_watch', 'backdrop', 'midnight', 'Полночь', 6),\n  ('sunset_watch', 'symbol', 'star', 'Звезда', 24),\n  ('sunset_watch', 'symbol', 'moon', 'Луна', 20),\n  ('sunset_watch', 'symbol', 'heart', 'Сердце', 18),\n  ('sunset_watch', 'symbol', 'diamond', 'Ромб', 14),\n  ('sunset_watch', 'symbol', 'leaf', 'Лист', 10),\n  ('sunset_watch', 'symbol', 'bolt', 'Молния', 8),\n  ('sunset_watch', 'symbol', 'sun', 'Солнце', 6)\non conflict do nothing;\n\n-- Обычный подарок «Часы»: купить, потом улучшить до уникального (цену можно менять через update public.gifts).\ninsert into public.gifts (id, title, description, image_url, price, collection, upgrade_price)\nvalues ('sunset_watch', 'Часы', 'Обычный подарок. Его можно улучшить до уникальных часов с редкой моделью, фоном и узором.', '', 100, 'sunset_watch', 50)\non conflict (id) do nothing;\n\nnotify pgrst, 'reload schema';\n"}
const patches = {"src/features/market/gifts.ts":{"one":[["export interface Gift { id: string; title: string; description: string; image_url: string; price: number; active: boolean }","export interface Gift { id: string; title: string; description: string; image_url: string; price: number; active: boolean; collection?: string | null; upgrade_price?: number }"],["select('id, title, description, image_url, price, active')","select('id, title, description, image_url, price, active, collection, upgrade_price')"]]},"src/features/market/GiftArt.tsx":{"one":[["import type { Gift } from './gifts'","import type { Gift } from './gifts'\nimport UniqueArt from './UniqueArt'"],["  if (gift.id === 'sunset_new_year') return <SunsetGift />","  if (gift.id === 'sunset_new_year') return <SunsetGift />\n  if (gift.id === 'sunset_watch') return <UniqueArt model=\"classic\" backdrop=\"sunset\" symbol=\"star\" label={gift.title} />"]]},"src/features/market/MarketPage.tsx":{"one":[["import GiftArt from './GiftArt'","import GiftArt from './GiftArt'\nimport { UniqueMine, UniqueShop } from './UniqueLists'\nimport { upgradeGift } from './unique'"],["{og.note && <div className=\"mt-1 text-xs\">{og.note}</div>}","{og.note && <div className=\"mt-1 text-xs\">{og.note}</div>}\n                      {g?.collection && (\n                        <button type=\"button\" className={smallBtn + ' mt-2'} disabled={busy}\n                          onClick={() => void run(async () => { await upgradeGift(og.id) })}>\n                          Улучшить до уникального{g.upgrade_price ? ' · ' + g.upgrade_price + ' ★' : ''}\n                        </button>\n                      )}"],["{mineKind === 'username' && <p className=\"text-sm text-muted\">В профиле: {me.handles.length} из 10</p>}","{mineKind === 'gift' && <UniqueMine meId={me.id} reloadKey={ownedGifts.length + ':' + stars} onChanged={() => { void refresh(); onProfileChanged() }} />}\n            {mineKind === 'username' && <p className=\"text-sm text-muted\">В профиле: {me.handles.length} из 10</p>}"],["{shownCount === 0 && <p className=\"text-sm text-muted\">Ничего не найдено. Измени фильтры или выстави свой лот.</p>}","{tab === 'gift' && <UniqueShop reloadKey={String(stars)} onChanged={() => { void refresh(); onProfileChanged() }} />}\n                {shownCount === 0 && <p className=\"text-sm text-muted\">Ничего не найдено. Измени фильтры или выстави свой лот.</p>}"]]}}

if (!existsSync('package.json') || !existsSync('src/features/market/MarketPage.tsx')) {
  console.error('Запускай из папки проекта (sunset-app).')
  process.exit(1)
}
if (existsSync('src/features/market/UniqueArt.tsx')) { console.log('Уже применено'); process.exit(0) }

const out = {}
const errors = []
for (const [file, spec] of Object.entries(patches)) {
  if (!existsSync(file)) { errors.push('нет файла ' + file); continue }
  const raw = readFileSync(file, 'utf8')
  const crlf = raw.includes('\r\n')
  let s = raw.replace(/\r\n/g, '\n')
  for (const [a, b] of spec.one) {
    const n = s.split(a).length - 1
    if (n !== 1) { errors.push(file + ': якорь найден ' + n + ' раз: ' + a.slice(0, 70).replace(/\n/g, ' ')); continue }
    s = s.replace(a, () => b)
  }
  out[file] = crlf ? s.replace(/\n/g, '\r\n') : s
}
if (errors.length) {
  console.error('Ничего не изменено. Проблемы:\n - ' + errors.join('\n - '))
  process.exit(1)
}
for (const [file, content] of Object.entries(out)) { writeFileSync(file, content); console.log('обновлён ' + file) }
for (const [file, content] of Object.entries(newFiles)) {
  mkdirSync(dirname(file), { recursive: true })
  writeFileSync(file, content)
  console.log('записан ' + file)
}
